#ifndef NN_ACCELERATOR_H
#define NN_ACCELERATOR_H

#include <stdint.h>
#include "xil_io.h"
#include "xstatus.h"
#include "xparameters.h"

/******************************************************************************
 * Register Map - NN Accelerator (Zynq-7000 / Pynq-Z2)
 *
 * The accelerator is instantiated in the FPGA fabric and communicated with
 * via AXI4-Lite (control/status/result) and AXI4-Stream (pixel data).
 *
 * TODO: Synchronise NN_BASE_ADDR with the address from xparameters.h
 *       generated by the Vitis platform based on the hardware specification
 *       (XSA). Typical allocation for an AXI Lite peripheral on Zynq is in
 *       the 0x43C00000 - 0x43FFFFFF range.
 ******************************************************************************/

/* Base address of the NN accelerator AXI-Lite slave interface */
#define NN_BASE_ADDR        XPAR_WEDROWIEC_REGS_0_BASEADDR


/******************************************************************************
 * Frame geometry
 ******************************************************************************/
#define NN_FRAME_WIDTH      8
#define NN_FRAME_HEIGHT     8
#define NN_FRAME_SIZE       (NN_FRAME_WIDTH * NN_FRAME_HEIGHT)  /* 64 bytes */

#define NN_UP 0x0
#define NN_LEFT 0x1
#define NN_DOWN 0x2
#define NN_RIGHT 0x3

/******************************************************************************
 * Public API
 ******************************************************************************/

typedef struct __attribute__((packed)) {
    uint32_t ctrl;
    uint32_t status;
    int32_t wedrowiec_result[4];
} wedrowiec_t;


/**
 * NN_TriggerAccelerator() - Trigger the accelerator to start processing.
 *
 * Asserts the Start bit in NN_CONTROL_REG. The frame data is expected
 * to have been loaded by the hardware (e.g. DMA) prior to calling this
 * function. After triggering, the caller should poll NN_STATUS_REG for
 * completion (e.g. wait until NN_STATUS_BUSY clears).
 */
void NN_TriggerAccelerator(volatile wedrowiec_t* wedrowiec);

/**
 * NN_GetDecision() - Read the classification result.
 *
 * @return  32-bit decision code from NN_RESULT_REG.
 *          The lower nibble encodes the command:
 *            0x0 = move forward
 *            0x1 = turn left
 *            0x2 = turn around
 *            0x3 = turn right
 */
uint32_t NN_GetDecision(volatile wedrowiec_t* wedrowiec);



#endif /* NN_ACCELERATOR_H */
